// Turns the TTFs in vendor/fonts into src/fonts.inc (C arrays), so the
// fonts are inside Glint.exe. The generated file is kept in the repo, like
// the compute shader's .spv.inc; rerun after changing a font:
//   node tools/embed_fonts.js
'use strict';
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const fonts = [
  ['kInterRegular', 'Inter-Regular.ttf'],
  ['kInterMedium', 'Inter-Medium.ttf'],
  ['kSpaceGroteskSemiBold', 'SpaceGrotesk-SemiBold.ttf'],
  ['kJetBrainsMonoRegular', 'JetBrainsMono-Regular.ttf'],
];
let out = '// Generated by tools/embed_fonts.js from vendor/fonts (SIL Open Font License 1.1,\n' +
          '// vendor/fonts/OFL-*.txt). Do not edit.\n';
for (const [name, file] of fonts) {
  const data = fs.readFileSync(path.join(root, 'vendor', 'fonts', file));
  out += `static const unsigned char ${name}[${data.length}] = {\n`;
  for (let i = 0; i < data.length; i += 24) {
    out += Array.from(data.subarray(i, i + 24), (b) => `0x${b.toString(16).padStart(2, '0')}`).join(',') + ',\n';
  }
  out += '};\n';
}
fs.writeFileSync(path.join(root, 'src', 'fonts.inc'), out);
console.log(`wrote src/fonts.inc (${fonts.length} fonts)`);
